//! Local-only ABI probe using public deployed Rhea Wasm, not a source rebuild.
//! No account/position/FT financial state is patched. Sandbox accounts only.
use std::sync::Arc;
use anyhow::{ensure,Result};
use near_api::{AccountId,Contract,NearGas,NearToken,NetworkConfig,Signer};
use near_api::types::transaction::result::ExecutionFinalResult;
use serde_json::{json,Value};
async fn view(c:&Contract,m:&str,a:Value,n:&NetworkConfig)->Result<Value>{let v:near_api::types::Data<Value>=c.call_function(m,a).read_only().fetch_from(n).await?;Ok(v.data)}
async fn call_gas(c:&Contract,m:&str,a:Value,id:&AccountId,s:Arc<Signer>,n:&NetworkConfig,deposit:u128,gas:u64)->Result<ExecutionFinalResult>{Ok(c.call_function(m,a).transaction().gas(NearGas::from_tgas(gas)).deposit(NearToken::from_yoctonear(deposit)).with_signer(id.clone(),s).send_to(n).await?.into_full().ok_or_else(||anyhow::anyhow!("nonfinal"))?)}
async fn call(c:&Contract,m:&str,a:Value,id:&AccountId,s:Arc<Signer>,n:&NetworkConfig,deposit:u128)->Result<ExecutionFinalResult>{call_gas(c,m,a,id,s,n,deposit,300).await}
async fn must(c:&Contract,m:&str,a:Value,id:&AccountId,s:Arc<Signer>,n:&NetworkConfig,deposit:u128)->Result<ExecutionFinalResult>{let f=call(c,m,a,id,s,n,deposit).await?;ensure!(f.is_success()&&f.receipt_failures().is_empty(),"{} failed: {:?}",m,f.receipt_failures());Ok(f)}
async fn deploy(id:AccountId,code:Vec<u8>,args:Value,s:Arc<Signer>,n:&NetworkConfig)->Result<()> {let f=Contract::deploy(id).use_code(code).with_init_call("new",args)?.gas(NearGas::from_tgas(300)).with_signer(s).send_to(n).await?.into_full().ok_or_else(||anyhow::anyhow!("nonfinal"))?;ensure!(f.is_success(),"deploy/init failed: {:?}",f.receipt_failures());Ok(())}
fn receipts(f:&ExecutionFinalResult)->Vec<Value>{f.receipt_outcomes().iter().map(|o|json!({"id":o.transaction_hash.to_string(),"executor":o.executor_id.to_string(),"success":o.is_success(),"failure":o.is_failure(),"children":o.receipt_ids.iter().map(ToString::to_string).collect::<Vec<_>>()})).collect()}
fn supplied(a:&Value,token:&str)->Result<(u128,u128)>{let rows=a.get("supplied").and_then(Value::as_array).ok_or_else(||anyhow::anyhow!("supplied missing"))?;ensure!(a.get("borrowed").and_then(Value::as_array).is_some_and(Vec::is_empty)&&a.get("collateral").and_then(Value::as_array).is_some_and(Vec::is_empty),"unexpected borrow/collateral");if rows.is_empty(){return Ok((0,0));}ensure!(rows.len()==1&&rows[0]["token_id"]==token,"wrong position");Ok((rows[0]["shares"].as_str().ok_or_else(||anyhow::anyhow!("shares missing"))?.parse()?,rows[0]["balance"].as_str().ok_or_else(||anyhow::anyhow!("balance missing"))?.parse()?))}
async fn balance(ft:&Contract,id:&AccountId,n:&NetworkConfig)->Result<u128>{Ok(view(ft,"ft_balance_of",json!({"account_id":id}),n).await?.as_str().ok_or_else(||anyhow::anyhow!("invalid balance"))?.parse()?)}
#[tokio::main] async fn main()->Result<()> {
 let rhea_bytes=std::fs::read(std::env::var("RHEA_WASM")?)?;let ft_bytes=std::fs::read(std::env::var("FT_WASM")?)?;
 let sb=near_sandbox::Sandbox::start_sandbox_with_version("2.14.0").await?;let n=NetworkConfig::from_rpc_url("sandbox",sb.rpc_addr.parse()?);let signer=Signer::from_secret_key(near_sandbox::config::DEFAULT_GENESIS_ACCOUNT_PRIVATE_KEY.parse()?)?;
 let owner:AccountId="owner.testnet".parse()?;let aid:AccountId="alice.testnet".parse()?;let bid:AccountId="bob.testnet".parse()?;let pid:AccountId="rhea.testnet".parse()?;let fid:AccountId="usdc.testnet".parse()?;
 for id in [&owner,&aid,&bid,&pid,&fid]{sb.create_account(id.as_str().parse()?).initial_balance(NearToken::from_near(60)).send().await?;}
 let metadata=json!({"spec":"ft-1.0.0","name":"Sandbox Mock USDC","symbol":"USDC","icon":null,"reference":null,"reference_hash":null,"decimals":6});
 deploy(fid.clone(),ft_bytes,json!({"owner_id":aid,"total_supply":"3000000","metadata":metadata}),signer.clone(),&n).await?;
 let config=json!({"oracle_account_id":"oracle.testnet","pyth_oracle_account_id":"pyth.testnet","ref_exchange_id":"ref.testnet","owner_id":owner,"booster_token_id":"boost.testnet","booster_decimals":18,"max_num_assets":20,"maximum_recency_duration_sec":90,"maximum_staleness_duration_sec":90,"lp_tokens_info_valid_duration_sec":600,"pyth_price_valid_duration_sec":60,"minimum_staking_duration_sec":2592000,"maximum_staking_duration_sec":7776000,"x_booster_multiplier_at_maximum_staking_duration":30000,"force_closing_enabled":true,"enable_price_oracle":false,"enable_pyth_oracle":true,"contract_mode":"Running","boost_suppress_factor":1000,"dcl_id":"dcl.testnet","pause_operator_id":null});
 deploy(pid.clone(),rhea_bytes,json!({"config":config}),signer.clone(),&n).await?;
 let ft=Contract(fid.clone());let provider=Contract(pid.clone());let observed_version=view(&provider,"get_version",json!({}),&n).await?;ensure!(observed_version=="0.16.2","unexpected Rhea version {observed_version}");
 let ac=json!({"reserve_ratio":2500,"beneficiaries":{},"target_utilization":8000,"target_utilization_rate":"1000000000001847694955734069","max_utilization_rate":"1000000000012857214234867166","holding_position_fee_rate":"1000000000000000000000000000","volatility_ratio":9500,"extra_decimals":12,"can_deposit":true,"can_withdraw":true,"can_use_as_collateral":false,"can_borrow":false,"net_tvl_multiplier":10000,"max_change_rate":null,"supplied_limit":"1000000000000000000000000","borrowed_limit":"0","min_borrowed_amount":"1"});
 let _=must(&provider,"add_asset",json!({"token_id":fid,"asset_config":ac}),&owner,signer.clone(),&n,1).await?;
 for id in [&pid,&bid]{let _=must(&ft,"storage_deposit",json!({"account_id":id}),&owner,signer.clone(),&n,10_000_000_000_000_000_000_000).await?;}
 for id in [&aid,&bid]{let _=must(&provider,"storage_deposit",json!({"account_id":id}),id,signer.clone(),&n,100_000_000_000_000_000_000_000).await?;}
 let _=must(&ft,"ft_transfer",json!({"receiver_id":bid,"amount":"1000000"}),&aid,signer.clone(),&n,1).await?;
 let mut supply_evidence=Vec::new();
 for (id,amount) in [(&aid,"2000000"),(&bid,"1000000")] {
  let f=call_gas(&ft,"ft_transfer_call",json!({"receiver_id":pid,"amount":amount,"msg":""}),id,signer.clone(),&n,1,60).await?;
  let used=f.clone().json::<String>().ok();let passed=f.is_success()&&f.receipt_failures().is_empty()&&used.as_deref()==Some(amount);
  let outcome=json!({"prepaid_tgas":60,"total_gas_burnt":f.total_gas_burnt.as_gas(),"success":f.is_success(),"used":used,"receipts":receipts(&f)});eprintln!("SUPPLY_60_RESULT {}",outcome);supply_evidence.push(outcome);ensure!(passed,"60 Tgas supply failed or refunded; do not retry without receipt reconciliation");
 }
 let before=view(&provider,"get_account",json!({"account_id":aid}),&n).await?;let before_a=supplied(&before,fid.as_str())?;ensure!(before_a.1==2_000_000_000_000_000_000,"unexpected internal supply");
 // Unregister Alice after spending her entire FT balance: receiver transfer fails.
 let _=must(&ft,"storage_unregister",json!({"force":false}),&aid,signer.clone(),&n,1).await?;
 let failed=call_gas(&provider,"simple_withdraw",json!({"token_id":fid,"amount_with_inner_decimal":"500000000000000000","recipient_id":aid}),&aid,signer.clone(),&n,1,90).await?;eprintln!("WITHDRAW_90_RESULT {}",json!({"case":"failed","prepaid_tgas":90,"total_gas_burnt":failed.total_gas_burnt.as_gas(),"success":failed.is_success(),"returned_bool":failed.clone().json::<bool>().ok(),"receipts":receipts(&failed)}));
 let failed_bool=failed.clone().json::<bool>()?;let after_failure=view(&provider,"get_account",json!({"account_id":aid}),&n).await?;let restored=supplied(&after_failure,fid.as_str())?;
 ensure!(!failed_bool&&failed.is_success()&&failed.receipt_failures().iter().any(|o|o.executor_id==fid)&&failed.receipt_outcomes().iter().any(|o|o.executor_id==pid&&o.is_success())&&restored==before_a,"failed transfer not restored");
 let _=must(&ft,"storage_deposit",json!({"account_id":aid}),&owner,signer.clone(),&n,10_000_000_000_000_000_000_000).await?;
 let partial=call_gas(&provider,"simple_withdraw",json!({"token_id":fid,"amount_with_inner_decimal":"500000000000000000","recipient_id":aid}),&aid,signer.clone(),&n,1,90).await?;eprintln!("WITHDRAW_90_RESULT {}",json!({"case":"partial","prepaid_tgas":90,"total_gas_burnt":partial.total_gas_burnt.as_gas(),"success":partial.is_success(),"returned_bool":partial.clone().json::<bool>().ok(),"receipts":receipts(&partial)}));ensure!(partial.is_success()&&partial.clone().json::<bool>()?&&partial.receipt_failures().is_empty()&&balance(&ft,&aid,&n).await?==500000,"partial unproven");
 let middle=view(&provider,"get_account",json!({"account_id":aid}),&n).await?;let middle_a=supplied(&middle,fid.as_str())?;ensure!(middle_a.1==1_500_000_000_000_000_000,"partial internal amount");
 let full=call_gas(&provider,"simple_withdraw",json!({"token_id":fid,"amount_with_inner_decimal":middle_a.1.to_string(),"recipient_id":aid}),&aid,signer.clone(),&n,1,90).await?;eprintln!("WITHDRAW_90_RESULT {}",json!({"case":"full","prepaid_tgas":90,"total_gas_burnt":full.total_gas_burnt.as_gas(),"success":full.is_success(),"returned_bool":full.clone().json::<bool>().ok(),"receipts":receipts(&full)}));ensure!(full.is_success()&&full.clone().json::<bool>()?&&full.receipt_failures().is_empty()&&balance(&ft,&aid,&n).await?==2000000,"full unproven");let final_a=supplied(&view(&provider,"get_account",json!({"account_id":aid}),&n).await?,fid.as_str())?;ensure!(final_a==(0,0),"full shares remain {final_a:?}");
 let before_b=supplied(&view(&provider,"get_account",json!({"account_id":bid}),&n).await?,fid.as_str())?;
 let dust=call_gas(&provider,"simple_withdraw",json!({"token_id":fid,"amount_with_inner_decimal":"1000000000001","recipient_id":bid}),&bid,signer.clone(),&n,1,90).await?;eprintln!("WITHDRAW_90_RESULT {}",json!({"case":"dust","prepaid_tgas":90,"total_gas_burnt":dust.total_gas_burnt.as_gas(),"success":dust.is_success(),"returned_bool":dust.clone().json::<bool>().ok(),"receipts":receipts(&dust)}));ensure!(dust.is_success()&&dust.clone().json::<bool>()?&&balance(&ft,&bid,&n).await?==1,"dust withdrawal unproven");let after_b=supplied(&view(&provider,"get_account",json!({"account_id":bid}),&n).await?,fid.as_str())?;ensure!(before_b.1-after_b.1==1_000_000_000_001,"unexpected internal dust delta");
 let tiny=call_gas(&provider,"simple_withdraw",json!({"token_id":fid,"amount_with_inner_decimal":"1","recipient_id":bid}),&bid,signer.clone(),&n,1,90).await?;eprintln!("WITHDRAW_90_RESULT {}",json!({"case":"tiny","prepaid_tgas":90,"total_gas_burnt":tiny.total_gas_burnt.as_gas(),"success":tiny.is_success(),"returned_bool":tiny.clone().json::<bool>().ok(),"receipts":receipts(&tiny)}));ensure!(tiny.is_failure(),"sub-token withdrawal did not fail");let final_b=supplied(&view(&provider,"get_account",json!({"account_id":bid}),&n).await?,fid.as_str())?;ensure!(final_b==after_b,"failed dust changed position");
 let asset=view(&provider,"get_asset",json!({"token_id":fid}),&n).await?;
 println!("{}",serde_json::to_string_pretty(&json!({"status":"PASS_LOCAL","scope":"Sandbox live public Rhea Wasm, local clean initialization; no financial state patch; no mainnet calls","version":observed_version,"asset":asset,"supply_60":supply_evidence,"alice_before":{"shares":before_a.0.to_string(),"internal":before_a.1.to_string()},"failed":{"prepaid_tgas":90,"total_gas_burnt":failed.total_gas_burnt.as_gas(),"top_success":failed.is_success(),"returned_bool":failed_bool,"receipts":receipts(&failed),"shares_restored":restored.0.to_string(),"internal_restored":restored.1.to_string()},"partial":{"prepaid_tgas":90,"total_gas_burnt":partial.total_gas_burnt.as_gas(),"returned_bool":true,"receipts":receipts(&partial),"shares":middle_a.0.to_string(),"internal":middle_a.1.to_string(),"ft":"500000"},"full":{"prepaid_tgas":90,"total_gas_burnt":full.total_gas_burnt.as_gas(),"returned_bool":true,"receipts":receipts(&full),"shares":final_a.0.to_string(),"internal":final_a.1.to_string(),"ft_total":"2000000"},"dust":{"prepaid_tgas":90,"total_gas_burnt":dust.total_gas_burnt.as_gas(),"requested_internal":"1000000000001","transferred_atomic":"1","before_shares":before_b.0.to_string(),"after_shares":after_b.0.to_string(),"before_internal":before_b.1.to_string(),"after_internal":after_b.1.to_string(),"sub_token_attempt_failed":tiny.is_failure(),"unchanged_on_failure":final_b==after_b,"receipts":receipts(&dust)}}))?);Ok(())
}
